//! A tiny backtracking pattern matcher supporting the subset of regular
//! expression syntax needed by the language heuristics.
//!
//! Supported syntax: literals, `.`, escapes (`\s`, `\S`, `\w`, `\W`, `\d`,
//! `\D`, `\b` and escaped punctuation), character classes (`[a-z_]`,
//! `[^)]`), groups with alternation (`(a|b)`), the quantifiers `*`, `+`, `?`
//! and the line anchor `^` (multi-line semantics) and `$`.

#[derive(Debug, Clone)]
enum ClassItem {
    Char(char),
    Range(char, char),
    Space(bool),
    Word(bool),
    Digit(bool),
}

#[derive(Debug, Clone)]
enum Node {
    Char(char),
    Any,
    Class(Vec<ClassItem>, bool),
    Space(bool),
    Word(bool),
    Digit(bool),
    LineStart,
    LineEnd,
    WordBoundary,
    Group(Vec<Vec<Node>>),
    Repeat(Box<Node>, usize, usize),
}

#[derive(Debug, Clone)]
pub struct Pattern {
    alts: Vec<Vec<Node>>,
}

fn is_word(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

struct Parser<'a> {
    chars: Vec<char>,
    pos: usize,
    _src: &'a str,
}

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.chars.get(self.pos).copied();
        self.pos += 1;
        c
    }

    fn parse_alts(&mut self) -> Vec<Vec<Node>> {
        let mut alts = vec![self.parse_seq()];
        while self.peek() == Some('|') {
            self.pos += 1;
            alts.push(self.parse_seq());
        }
        alts
    }

    fn parse_seq(&mut self) -> Vec<Node> {
        let mut seq = Vec::new();
        while let Some(c) = self.peek() {
            if c == '|' || c == ')' {
                break;
            }
            let atom = self.parse_atom();
            let atom = self.parse_quant(atom);
            seq.push(atom);
        }
        seq
    }

    fn parse_quant(&mut self, atom: Node) -> Node {
        match self.peek() {
            Some('*') => {
                self.pos += 1;
                Node::Repeat(Box::new(atom), 0, usize::MAX)
            }
            Some('+') => {
                self.pos += 1;
                Node::Repeat(Box::new(atom), 1, usize::MAX)
            }
            Some('?') => {
                self.pos += 1;
                Node::Repeat(Box::new(atom), 0, 1)
            }
            _ => atom,
        }
    }

    fn parse_escape_in_class(&mut self) -> ClassItem {
        match self.next() {
            Some('s') => ClassItem::Space(true),
            Some('S') => ClassItem::Space(false),
            Some('w') => ClassItem::Word(true),
            Some('W') => ClassItem::Word(false),
            Some('d') => ClassItem::Digit(true),
            Some('D') => ClassItem::Digit(false),
            Some('n') => ClassItem::Char('\n'),
            Some('t') => ClassItem::Char('\t'),
            Some(c) => ClassItem::Char(c),
            None => ClassItem::Char('\\'),
        }
    }

    fn parse_atom(&mut self) -> Node {
        let c = self.next().unwrap();
        match c {
            '.' => Node::Any,
            '^' => Node::LineStart,
            '$' => Node::LineEnd,
            '(' => {
                let alts = self.parse_alts();
                if self.peek() == Some(')') {
                    self.pos += 1;
                }
                Node::Group(alts)
            }
            '[' => {
                let mut negated = false;
                if self.peek() == Some('^') {
                    negated = true;
                    self.pos += 1;
                }
                let mut items = Vec::new();
                let mut first = true;
                while let Some(c) = self.next() {
                    if c == ']' && !first {
                        break;
                    }
                    first = false;
                    let item = if c == '\\' {
                        self.parse_escape_in_class()
                    } else {
                        ClassItem::Char(c)
                    };
                    if let ClassItem::Char(lo) = item {
                        if self.peek() == Some('-')
                            && self.chars.get(self.pos + 1).map_or(false, |&n| n != ']')
                        {
                            self.pos += 1;
                            let hi = self.next().unwrap();
                            items.push(ClassItem::Range(lo, hi));
                            continue;
                        }
                    }
                    items.push(item);
                }
                Node::Class(items, negated)
            }
            '\\' => match self.next() {
                Some('s') => Node::Space(true),
                Some('S') => Node::Space(false),
                Some('w') => Node::Word(true),
                Some('W') => Node::Word(false),
                Some('d') => Node::Digit(true),
                Some('D') => Node::Digit(false),
                Some('b') => Node::WordBoundary,
                Some('n') => Node::Char('\n'),
                Some('t') => Node::Char('\t'),
                Some(c) => Node::Char(c),
                None => Node::Char('\\'),
            },
            c => Node::Char(c),
        }
    }
}

fn class_item_matches(item: &ClassItem, c: char) -> bool {
    match *item {
        ClassItem::Char(x) => x == c,
        ClassItem::Range(lo, hi) => lo <= c && c <= hi,
        ClassItem::Space(pos) => c.is_whitespace() == pos,
        ClassItem::Word(pos) => is_word(c) == pos,
        ClassItem::Digit(pos) => c.is_ascii_digit() == pos,
    }
}

fn single_matches(node: &Node, c: char) -> Option<bool> {
    Some(match node {
        Node::Char(x) => *x == c,
        Node::Any => c != '\n',
        Node::Class(items, negated) => items.iter().any(|i| class_item_matches(i, c)) != *negated,
        Node::Space(pos) => c.is_whitespace() == *pos,
        Node::Word(pos) => is_word(c) == *pos,
        Node::Digit(pos) => c.is_ascii_digit() == *pos,
        _ => return None,
    })
}

impl Pattern {
    pub fn new(src: &str) -> Pattern {
        let mut p = Parser {
            chars: src.chars().collect(),
            pos: 0,
            _src: src,
        };
        let alts = p.parse_alts();
        Pattern { alts }
    }

    /// Returns true when the pattern matches anywhere in `text`.
    pub fn is_match(&self, text: &str) -> bool {
        let chars: Vec<char> = text.chars().collect();
        for start in 0..=chars.len() {
            for alt in &self.alts {
                if match_seq(alt, 0, &chars, start, &mut |_| true) {
                    return true;
                }
            }
        }
        false
    }
}

fn match_seq(seq: &[Node], idx: usize, s: &[char], pos: usize, k: &mut dyn FnMut(usize) -> bool) -> bool {
    if idx == seq.len() {
        return k(pos);
    }
    let node = &seq[idx];
    match node {
        Node::LineStart => {
            if pos == 0 || s[pos - 1] == '\n' {
                match_seq(seq, idx + 1, s, pos, k)
            } else {
                false
            }
        }
        Node::LineEnd => {
            if pos == s.len() || s[pos] == '\n' {
                match_seq(seq, idx + 1, s, pos, k)
            } else {
                false
            }
        }
        Node::WordBoundary => {
            let before = pos > 0 && is_word(s[pos - 1]);
            let after = pos < s.len() && is_word(s[pos]);
            if before != after {
                match_seq(seq, idx + 1, s, pos, k)
            } else {
                false
            }
        }
        Node::Group(alts) => {
            for alt in alts {
                let mut cont = |p: usize| match_seq(seq, idx + 1, s, p, k);
                if match_seq(alt, 0, s, pos, &mut cont) {
                    return true;
                }
            }
            false
        }
        Node::Repeat(inner, min, max) => match_repeat(inner, *min, *max, 0, seq, idx, s, pos, k),
        _ => {
            if pos < s.len() && single_matches(node, s[pos]) == Some(true) {
                match_seq(seq, idx + 1, s, pos + 1, k)
            } else {
                false
            }
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn match_repeat(
    inner: &Node,
    min: usize,
    max: usize,
    count: usize,
    seq: &[Node],
    idx: usize,
    s: &[char],
    pos: usize,
    k: &mut dyn FnMut(usize) -> bool,
) -> bool {
    // Greedy: try one more repetition first.
    if count < max {
        let one = std::slice::from_ref(inner);
        let mut more = |p: usize| {
            if p == pos {
                return false;
            }
            match_repeat(inner, min, max, count + 1, seq, idx, s, p, k)
        };
        if match_seq(one, 0, s, pos, &mut more) {
            return true;
        }
    }
    if count >= min {
        return match_seq(seq, idx + 1, s, pos, k);
    }
    false
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basics() {
        assert!(Pattern::new(r"^import\s+[\w.]").is_match("x\nimport os"));
        assert!(!Pattern::new(r"^import\s+[\w.]").is_match("x import os"));
        assert!(Pattern::new(r"\$\([^)]+\)").is_match("a $(ls) b"));
        assert!(!Pattern::new(r"\$\([^)]+\)").is_match("a $() b"));
        assert!(Pattern::new(r"^#!\s*/(usr/)?bin/(env\s+)?(ba)?sh").is_match("#!/usr/bin/env bash"));
        assert!(Pattern::new(r"^#!\s*/(usr/)?bin/(env\s+)?(ba)?sh").is_match("#!/bin/sh"));
        assert!(!Pattern::new(r"^#!\s*/(usr/)?bin/(env\s+)?(ba)?sh").is_match("#!/bin/dash"));
        assert!(Pattern::new(r"^use\s+(strict|warnings)\b").is_match("use strict;"));
        assert!(!Pattern::new(r"^use\s+(strict|warnings)\b").is_match("use strictx"));
        assert!(Pattern::new(r"^[A-Za-z_][\w.]*\s*<-").is_match("x.y <- 1"));
        assert!(!Pattern::new(r"^[A-Za-z_][\w.]*\s*<-").is_match("1 <- 1"));
    }
}
EOF
