use std::fmt;

/// Minimal error type carrying a message and an optional chain of causes,
/// rendered in the same style as `anyhow`'s debug representation.
pub struct Error {
    msg: String,
    source: Option<Box<Error>>,
}

pub type Result<T> = std::result::Result<T, Error>;

impl Error {
    pub fn msg<S: Into<String>>(s: S) -> Error {
        Error { msg: s.into(), source: None }
    }

    pub fn context<S: Into<String>>(self, s: S) -> Error {
        Error { msg: s.into(), source: Some(Box::new(self)) }
    }

    pub fn render(&self) -> String {
        let mut out = self.msg.clone();
        let mut causes = Vec::new();
        let mut cur = self.source.as_deref();
        while let Some(c) = cur {
            causes.push(c.msg.clone());
            cur = c.source.as_deref();
        }
        if !causes.is_empty() {
            out.push_str("\n\nCaused by:");
            if causes.len() == 1 {
                out.push_str("\n    ");
                out.push_str(&indent_continuation(&causes[0], "    "));
            } else {
                for (i, c) in causes.iter().enumerate() {
                    out.push_str(&format!("\n    {}: ", i));
                    out.push_str(&indent_continuation(c, "       "));
                }
            }
        }
        out
    }
}

fn indent_continuation(s: &str, pad: &str) -> String {
    let mut out = String::new();
    for (i, line) in s.split('\n').enumerate() {
        if i > 0 {
            out.push('\n');
            if !line.is_empty() {
                out.push_str(pad);
            }
        }
        out.push_str(line);
    }
    out
}

impl fmt::Debug for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.render())
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.msg)
    }
}

impl From<std::io::Error> for Error {
    fn from(e: std::io::Error) -> Error {
        Error::msg(e.to_string())
    }
}

pub trait Context<T> {
    fn context<S: Into<String>>(self, s: S) -> Result<T>;
    fn with_context<S: Into<String>, F: FnOnce() -> S>(self, f: F) -> Result<T>;
}

impl<T, E: Into<Error>> Context<T> for std::result::Result<T, E> {
    fn context<S: Into<String>>(self, s: S) -> Result<T> {
        self.map_err(|e| e.into().context(s))
    }

    fn with_context<S: Into<String>, F: FnOnce() -> S>(self, f: F) -> Result<T> {
        self.map_err(|e| e.into().context(f()))
    }
}

#[macro_export]
macro_rules! bail {
    ($($arg:tt)*) => {
        return Err($crate::error::Error::msg(format!($($arg)*)))
    };
}
