}

/// Map a file extension to a language id.
pub fn from_extension(path: &Path) -> Option<&'static str> {
    let ext = path.extension()?.to_str()?.to_lowercase();
    let lang = match ext.as_str() {
        "py" | "pyw" | "py3" => "python",
        "js" | "mjs" | "cjs" | "jsx" => "javascript",
        "ts" | "tsx" => "typescript",
        "c" => "c",
        "cpp" | "cc" | "cxx" | "hpp" | "hxx" => "cpp",
        "rs" => "rust",
        "go" => "go",
        "sh" | "bash" | "zsh" => "bash",
        "pl" | "pm" => "perl",
        "rb" => "ruby",
        "java" => "java",
        "kt" | "kts" => "kotlin",
        "lua" => "lua",
        "php" => "php",
        "swift" => "swift",
        "ex" | "exs" => "elixir",
        "hs" => "haskell",
        "jl" => "julia",
        "cs" => "csharp",
        "r" => "r",
        "cr" => "crystal",
        "dart" => "dart",
        "groovy" => "groovy",
        "nim" => "nim",
        "zig" => "zig",
        _ => return None,
    };
    Some(lang)
}

const PATH_LIKE_EXTENSIONS: &[&str] = &[
    "py", "pyw", "js", "mjs", "cjs", "jsx", "ts", "tsx", "c", "h", "hpp", "cc", "cpp", "rs", "go",
    "sh", "bash", "zsh", "pl", "rb", "java", "kt", "lua", "php", "swift", "ex", "exs", "hs", "jl",
    "cs", "fs", "ml", "scala", "clj", "ps1",
];

/// Heuristic used for a lone positional argument: does it look like a path
/// to a source file rather than an inline snippet?
pub fn looks_like_path(arg: &str) -> bool {
    if arg.contains('/') || arg.contains('\\') {
        return true;
    }
    let p = Path::new(arg);
    if p.exists() {
        return true;
    }
    if let Some(ext) = p.extension().and_then(|e| e.to_str()) {
        let ext = ext.to_lowercase();
        return PATH_LIKE_EXTENSIONS.contains(&ext.as_str());
    }
    false
}
