use std::ffi::OsString;
use std::fs;
use std::io::{self, Read, Write};
use std::os::unix::fs::PermissionsExt;
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Output, Stdio};
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::{SystemTime, UNIX_EPOCH};

/// Locate an executable on PATH, returning its full path.
pub fn which(name: &str) -> Option<PathBuf> {
    if name.contains('/') {
        let p = PathBuf::from(name);
        return if is_executable(&p) { Some(p) } else { None };
    }
    let path = std::env::var_os("PATH")?;
    for dir in std::env::split_paths(&path) {
        let dir = if dir.as_os_str().is_empty() {
            match std::env::current_dir() {
                Ok(d) => d,
                Err(_) => continue,
            }
        } else {
            dir
        };
        let candidate = dir.join(name);
        if is_executable(&candidate) {
            return Some(candidate);
        }
    }
    None
}

fn is_executable(p: &Path) -> bool {
    match fs::metadata(p) {
        Ok(m) => m.is_file() && m.permissions().mode() & 0o111 != 0,
        Err(_) => false,
    }
}

/// Probe a tool by asking for its version; the result is ignored.
pub fn probe(path: &Path, arg: &str) {
    let _ = Command::new(path)
        .arg(arg)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status();
}

/// Find the first available candidate and probe it.
pub fn find_tool(candidates: &[&str], version_arg: &str) -> Option<PathBuf> {
    for c in candidates {
        if let Some(p) = which(c) {
            probe(&p, version_arg);
            return Some(p);
        }
    }
    None
}

static COUNTER: AtomicU64 = AtomicU64::new(0);

fn random_state() -> u64 {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64)
        .unwrap_or(0);
    let c = COUNTER.fetch_add(1, Ordering::SeqCst);
    let mut x = now ^ ((std::process::id() as u64) << 32) ^ c.wrapping_mul(0x9E3779B97F4A7C15);
    if x == 0 {
        x = 0x2545F4914F6CDD1D;
    }
    x
}

pub fn random_name(len: usize) -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    let mut x = random_state();
    let mut s = String::with_capacity(len);
    for _ in 0..len {
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        s.push(CHARS[(x % CHARS.len() as u64) as usize] as char);
    }
    s
}

/// A temporary directory removed on drop.
pub struct TempDir {
    path: PathBuf,
}

impl TempDir {
    pub fn new(prefix: &str) -> io::Result<TempDir> {
        let base = std::env::temp_dir();
        for _ in 0..64 {
            let p = base.join(format!("{}{}", prefix, random_name(6)));
            let mut b = fs::DirBuilder::new();
            std::os::unix::fs::DirBuilderExt::mode(&mut b, 0o700);
            match b.create(&p) {
                Ok(()) => return Ok(TempDir { path: p }),
                Err(e) if e.kind() == io::ErrorKind::AlreadyExists => continue,
                Err(e) => return Err(e),
            }
        }
        Err(io::Error::new(io::ErrorKind::AlreadyExists, "too many temporary files exist"))
    }

    pub fn path(&self) -> &Path {
        &self.path
    }
}

impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.path);
    }
}

/// A temporary file removed on drop.
pub struct TempFile {
    path: PathBuf,
}

impl TempFile {
    pub fn new(prefix: &str, suffix: &str, contents: &str) -> io::Result<TempFile> {
        let base = std::env::temp_dir();
        for _ in 0..64 {
            let p = base.join(format!("{}{}{}", prefix, random_name(6), suffix));
            let mut opts = fs::OpenOptions::new();
            opts.write(true).create_new(true);
            std::os::unix::fs::OpenOptionsExt::mode(&mut opts, 0o600);
            match opts.open(&p) {
                Ok(mut f) => {
                    f.write_all(contents.as_bytes())?;
                    return Ok(TempFile { path: p });
                }
                Err(e) if e.kind() == io::ErrorKind::AlreadyExists => continue,
                Err(e) => return Err(e),
            }
        }
        Err(io::Error::new(io::ErrorKind::AlreadyExists, "too many temporary files exist"))
    }

    pub fn path(&self) -> &Path {
        &self.path
    }
}

impl Drop for TempFile {
    fn drop(&mut self) {
        let _ = fs::remove_file(&self.path);
    }
}

/// Print captured output (lossily decoded) and return the exit code.
pub fn emit(out: &Output) -> i32 {
    let so = String::from_utf8_lossy(&out.stdout);
    let se = String::from_utf8_lossy(&out.stderr);
    {
        let mut o = io::stdout();
        let _ = o.write_all(so.as_bytes());
        let _ = o.flush();
    }
    {
        let mut e = io::stderr();
        let _ = e.write_all(se.as_bytes());
        let _ = e.flush();
    }
    exit_code(out)
}

pub fn exit_code(out: &Output) -> i32 {
    out.status.code().unwrap_or(0)
}

/// Run a command with inherited stdin and captured stdout/stderr.
pub fn capture(cmd: &mut Command) -> io::Result<Output> {
    cmd.stdin(Stdio::inherit()).stdout(Stdio::piped()).stderr(Stdio::piped());
    cmd.output()
}

/// Spawn a command with piped stdin (stdout/stderr captured).
pub fn spawn_piped(cmd: &mut Command) -> io::Result<Child> {
    cmd.stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped());
    cmd.spawn()
}

/// Feed `input` to a spawned child's stdin and collect its output.
pub fn feed_and_wait(mut child: Child, input: &str) -> io::Result<Output> {
    if let Some(mut stdin) = child.stdin.take() {
        stdin.write_all(input.as_bytes())?;
    }
    child.wait_with_output()
}

pub fn read_stdin_to_string() -> io::Result<String> {
    let mut s = String::new();
    io::stdin().read_to_string(&mut s)?;
    Ok(s)
}

pub fn display(p: &Path) -> String {
    p.display().to_string()
}

#[allow(dead_code)]
pub fn os(s: &str) -> OsString {
    OsString::from(s)
}
