pub fn ensure_newline(code: &str) -> String {
    let mut s = code.to_string();
    if !s.ends_with('\n') {
        s.push('\n');
    }
    s
}

fn parent_dir(path: &Path) -> Option<PathBuf> {
    path.parent().map(|p| p.to_path_buf())
}

fn file_name(path: &Path) -> String {
    path.file_name()
        .map(|f| f.to_string_lossy().into_owned())
        .unwrap_or_else(|| display(path))
}

fn require(candidates: &[&str], version_arg: &str, missing: &str) -> Result<PathBuf> {
    match find_tool(candidates, version_arg) {
        Some(p) => Ok(p),
        None => Err(Error::msg(missing)),
    }
}

fn tool_or(candidates: &[&str], version_arg: &str, fallback: &str) -> PathBuf {
    find_tool(candidates, version_arg).unwrap_or_else(|| PathBuf::from(fallback))
}

