const DENO_HINT: &str = "Install Deno from https://deno.land/manual/getting_started/installation or ensure the binary is available on your PATH.";

fn typescript(payload: &Payload) -> Result<i32> {
    let deno = find_tool(&["deno"], "--version");
    let deno = match (deno, payload) {
        (Some(d), _) => d,
        (None, Payload::Inline(_)) => bail!("failed to run Deno for inline execution because 'deno' was not found in PATH. {}", DENO_HINT),
        (None, Payload::File(_)) => bail!("failed to run Deno for file execution because 'deno' was not found in PATH. {}", DENO_HINT),
        (None, Payload::Stdin(_)) => bail!("failed to start Deno for stdin execution because 'deno' was not found in PATH. {}", DENO_HINT),
    };
    let base = ["run", "--quiet", "--no-check", "--ext", "ts"];
    match payload {
        Payload::Inline(code) => {
            let tmp = TempFile::new(".tmp", "", &ensure_newline(code))?;
            let out = capture(Command::new(&deno).args(base).arg(tmp.path()))?;
            Ok(emit(&out))
        }
        Payload::File(path) => {
            let out = capture(Command::new(&deno).args(base).arg(path))?;
            Ok(emit(&out))
        }
        Payload::Stdin(code) => {
            let child = spawn_piped(Command::new(&deno).args(base).arg("-"))
                .with_context(|| format!("failed to start {} for stdin execution", display(&deno)))?;
            let out = feed_and_wait(child, code)?;
            Ok(emit(&out))
        }
    }
}

