fn run_script_file(exe: &Path, spec: &ScriptSpec, script: &Path, cwd: Option<&Path>) -> Result<i32> {
    let mut cmd = Command::new(exe);
    cmd.args(spec.pre_args).arg(script).args(spec.post_args);
    if let Some(d) = cwd {
        cmd.current_dir(d);
    }
    let out = capture(&mut cmd).with_context(|| {
        format!("failed to execute {} with {} {}", display(exe), spec.verb, display(script))
    })?;
    Ok(emit(&out))
}

fn script_engine_with(payload: &Payload, spec: &ScriptSpec, prepare: &dyn Fn(&str) -> String) -> Result<i32> {
    let exe = require(spec.candidates, spec.version_arg, spec.missing)?;
    match payload {
        Payload::Inline(code) | Payload::Stdin(code) => {
            let dir = TempDir::new(spec.prefix)?;
            let script = dir.path().join(spec.file);
            fs::write(&script, prepare(code))?;
            run_script_file(&exe, spec, &script, Some(dir.path()))
        }
        Payload::File(path) => {
            let parent = parent_dir(path);
            run_script_file(&exe, spec, path, parent.as_deref())
        }
    }
}

fn script_engine(payload: &Payload, spec: &ScriptSpec) -> Result<i32> {
    script_engine_with(payload, spec, &|c| ensure_newline(c))
}

fn perl(payload: &Payload) -> Result<i32> {
    script_engine(payload, &PERL)
}

fn php(payload: &Payload) -> Result<i32> {
    script_engine_with(payload, &PHP, &|c| {
        if c.starts_with("<?php") {
            ensure_newline(c)
        } else {
            format!("<?php\n{}", ensure_newline(c))
        }
    })
}

fn r_lang(payload: &Payload) -> Result<i32> {
