pub fn wrap_c(code: &str) -> String {
    if code.contains("#include") || code.contains("main(") {
        return code.to_string();
    }
    format!(
        "#include <stdio.h>\n\nint main(void)\n{{\n{}    return 0;\n}}\n",
        indent_body(code, "    ")
    )
}

fn c_family(payload: &Payload, spec: &CFamily) -> Result<i32> {
    let dir = TempDir::new(spec.prefix)?;
    let source = dir.path().join(spec.source);
    match payload {
        Payload::Inline(code) | Payload::Stdin(code) => {
            let text = if spec.wrap { wrap_c(code) } else { code.clone() };
            fs::write(&source, text)?;
        }
        Payload::File(path) => {
            fs::copy(path, &source).with_context(|| {
                format!(
                    "failed to copy {} source from {} to {}",
                    spec.label,
                    display(path),
                    display(&source)
                )
            })?;
        }
    }
    let compiler = require(spec.candidates, "--version", spec.missing)?;
    let binary = dir.path().join(spec.binary);
    let out = Command::new(&compiler)
        .arg(&source)
        .arg(spec.std)
        .args(["-O0", "-Wall", "-Wextra", "-o"])
        .arg(&binary)
        .stdin(std::process::Stdio::null())
        .output()
        .with_context(|| format!("failed to invoke {}", display(&compiler)))?;
    if !out.status.success() {
        return Ok(emit(&out));
    }
    run_binary(&binary)
}

// ------------------------------------------------------------------ java ---

fn split_imports(code: &str, prefixes: &[&str]) -> (Vec<String>, Vec<String>) {
    let mut imports = Vec::new();
    let mut body = Vec::new();
    for line in code.lines() {
        let t = line.trim_start();
        if prefixes.iter().any(|p| t.starts_with(p)) {
            imports.push(line.trim().to_string());
        } else {
            body.push(line.to_string());
        }
    }
    (imports, body)
}

fn java(payload: &Payload) -> Result<i32> {
    let javac = require(
        &["javac"],
        "-version",
        "Java support requires the `javac` compiler. Install the JDK from https://adoptium.net/ or your vendor of choice and ensure it is on your PATH.",
    )?;
    let java = find_tool(&["java"], "-version");
    let dir = TempDir::new("run-java")?;
    let (source, class) = match payload {
        Payload::Inline(code) | Payload::Stdin(code) => {
            let text = if code.contains("class ") {
                code.clone()
            } else {
                let (imports, body) = split_imports(code, &["import "]);
                let mut s = String::new();
                if !imports.is_empty() {
                    s.push_str(&imports.join("\n"));
                    s.push_str("\n\n");
                }
                s.push_str("public class Main {\n    public static void main(String[] args) throws Exception {\n");
                s.push_str(&indent_body(&body.join("\n"), "        "));
                s.push_str("    }\n}\n");
                s
            };
            let f = dir.path().join("Main.java");
            fs::write(&f, text)?;
            (f, "Main".to_string())
        }
        Payload::File(path) => {
            let name = file_name(path);
            let f = dir.path().join(&name);
            fs::copy(path, &f)?;
            let stem = path
                .file_stem()
                .map(|s| s.to_string_lossy().into_owned())
                .unwrap_or_else(|| "Main".to_string());
            (f, stem)
        }
    };
    let out = Command::new(&javac)
        .arg("-d")
        .arg(dir.path())
        .arg(&source)
        .stdin(std::process::Stdio::null())
        .output()
        .with_context(|| format!("failed to invoke {}", display(&javac)))?;
    if !out.status.success() {
        return Ok(emit(&out));
    }
    let java = match java {
        Some(j) => j,
        None => bail!("Java support requires the `java` runtime. Install the JDK from https://adoptium.net/ or your vendor of choice and ensure it is on your PATH."),
    };
    let out = capture(Command::new(&java).arg("-cp").arg(dir.path()).arg(&class))?;
    Ok(emit(&out))
}

// ---------------------------------------------------------------- kotlin ---

fn kotlin(payload: &Payload) -> Result<i32> {
    let kotlinc = require(
        &["kotlinc"],
        "-version",
        "Kotlin support requires the `kotlinc` compiler. Install it from https://kotlinlang.org/docs/command-line.html and ensure it is on your PATH.",
    )?;
    let java = find_tool(&["java"], "-version");
    let dir = TempDir::new("run-kotlin")?;
    let source = match payload {
        Payload::Inline(code) | Payload::Stdin(code) => {
            let text = if code.contains("fun main") {
                code.clone()
            } else {
                let (imports, body) = split_imports(code, &["import "]);
                let mut s = String::new();
                if !imports.is_empty() {
                    s.push_str(&imports.join("\n"));
                    s.push_str("\n\n");
                }
                s.push_str("fun main() {\n");
                s.push_str(&indent_body(&body.join("\n"), "    "));
                s.push_str("}\n");
                s
            };
            let f = dir.path().join("Main.kt");
            fs::write(&f, text)?;
            f
        }
        Payload::File(path) => {
            let f = dir.path().join(file_name(path));
            fs::copy(path, &f)?;
            f
        }
    };
    let jar = dir.path().join("snippet.jar");
    let out = Command::new(&kotlinc)
        .arg(&source)
        .arg("-include-runtime")
        .arg("-d")
        .arg(&jar)
        .stdin(std::process::Stdio::null())
        .output()
        .with_context(|| format!("failed to invoke {}", display(&kotlinc)))?;
    if !out.status.success() {
        return Ok(emit(&out));
    }
    let java = match java {
        Some(j) => j,
        None => bail!("Kotlin execution requires a `java` runtime. Install a JDK and ensure `java` is on your PATH."),
    };
    let out = capture(Command::new(&java).arg("-jar").arg(&jar))?;
    Ok(emit(&out))
}

// ------------------------------------------------------------------ dart ---

fn dart(payload: &Payload) -> Result<i32> {
    let exe = require(
        &["dart"],
        "--version",
        "Dart support requires the `dart` executable. Install the Dart SDK from https://dart.dev/get-dart and ensure `dart` is on your PATH.",
    )?;
    match payload {
        Payload::Inline(code) | Payload::Stdin(code) => {
            let dir = TempDir::new("run-dart")?;
            let text = if code.contains("main(") {
                ensure_newline(code)
            } else {
                let mut body = String::new();
                for line in code.lines() {
                    let t = line.trim_end();
                    if t.trim().is_empty() {
                        body.push('\n');
                        continue;
                    }
                    body.push_str("  ");
                    body.push_str(t);
                    if !(t.ends_with(';') || t.ends_with('{') || t.ends_with('}')) {
                        body.push(';');
                    }
                    body.push('\n');
                }
                format!("Future<void> main() async {{\n{}}}\n", body)
            };
            let file = dir.path().join("main.dart");
            fs::write(&file, text)?;
            let out = capture(
                Command::new(&exe)
                    .args(["run", "--enable-asserts", "main.dart"])
                    .current_dir(dir.path()),
            )
            .with_context(|| format!("failed to invoke {} to run {}", display(&exe), display(&file)))?;
            Ok(emit(&out))
        }
        Payload::File(path) => {
            let mut cmd = Command::new(&exe);
            cmd.args(["run", "--enable-asserts"]).arg(file_name(path));
            if let Some(p) = parent_dir(path) {
                cmd.current_dir(p);
            }
            let out = capture(&mut cmd)
                .with_context(|| format!("failed to invoke {} to run {}", display(&exe), display(path)))?;
            Ok(emit(&out))
        }
    }
}

// ---------------------------------------------------------------- groovy ---

fn groovy_prepare(code: &str) -> String {
    if code.contains("println") {
        return code.to_string();
    }
    let last = code.lines().rev().find(|l| !l.trim().is_empty()).map(|l| l.trim().to_string());
    match last {
        Some(l) if groovy_is_expression(&l) => {
            let mut s = ensure_newline(code);
            s.push_str(&format!("println({});\n", l.trim_end_matches(';')));
            s
        }
        _ => code.to_string(),
    }
}

fn groovy_is_expression(line: &str) -> bool {
    const KEYWORDS: &[&str] = &[
        "def ", "class ", "import ", "package ", "if ", "if(", "for ", "for(", "while ", "while(",
        "return", "print", "interface ", "enum ", "static ", "public ", "private ", "//", "/*", "*",
    ];
    if KEYWORDS.iter().any(|k| line.starts_with(k)) {
        return false;
    }
    !(line.ends_with('{') || line.ends_with('}'))
}

fn groovy(payload: &Payload) -> Result<i32> {
    let exe = require(
        &["groovy"],
        "--version",
        "Groovy support requires the `groovy` executable. Install it from https://groovy-lang.org/download.html and make sure it is available on your PATH.",
    )?;
    match payload {
        Payload::Inline(code) => {
            let out = capture(Command::new(&exe).arg("-e").arg(groovy_prepare(code)))?;
            Ok(emit(&out))
        }
        Payload::File(path) => {
            let out = capture(Command::new(&exe).arg(path))?;
            Ok(emit(&out))
        }
        Payload::Stdin(code) => {
            let tmp = TempFile::new("run-groovy-stdin", ".groovy", &groovy_prepare(code))?;
            let out = capture(Command::new(&exe).arg(tmp.path()))?;
            Ok(emit(&out))
        }
    }
}

// ---------------------------------------------------------------- csharp ---

pub fn dotnet_target_framework(dotnet: &Path) -> Option<String> {
    let out = Command::new(dotnet)
        .arg("--list-sdks")
        .stdin(std::process::Stdio::null())
        .output()
        .ok()?;
    let text = String::from_utf8_lossy(&out.stdout);
    let mut best: Option<(u32, u32)> = None;
    for line in text.lines() {
        let ver = line.split_whitespace().next().unwrap_or("");
        let mut parts = ver.split('.');
        let major = parts.next().and_then(|p| p.parse::<u32>().ok());
        let minor = parts.next().and_then(|p| p.parse::<u32>().ok());
        if let (Some(ma), Some(mi)) = (major, minor) {
            if best.map_or(true, |b| (ma, mi) > b) {
                best = Some((ma, mi));
            }
        }
    }
    best.map(|(ma, mi)| format!("net{}.{}", ma, mi))
}

/// Called once at start-up, mirroring the engine registry bootstrap.
pub fn bootstrap() {
    if let Some(d) = sys::which("dotnet") {
        let _ = dotnet_target_framework(&d);
    }
}

fn csharp(payload: &Payload) -> Result<i32> {
    let dotnet = match sys::which("dotnet") {
        Some(d) => d,
        None => bail!("C# support requires the `dotnet` CLI. Install the .NET SDK from https://dotnet.microsoft.com/download and ensure `dotnet` is on your PATH."),
    };
    let tfm = match dotnet_target_framework(&dotnet) {
        Some(t) => t,
        None => bail!("Unable to detect installed .NET SDK target framework"),
    };
    let dir = TempDir::new("run-csharp")?;
    let project = dir.path().join("Run.csproj");
    let csproj = format!(
        "<Project Sdk=\"Microsoft.NET.Sdk\">\n  <PropertyGroup>\n    <OutputType>Exe</OutputType>\n    <TargetFramework>{}</TargetFramework>\n    <ImplicitUsings>enable</ImplicitUsings>\n    <Nullable>disable</Nullable>\n        <NoWarn>CS0219;CS8321</NoWarn>\n  </PropertyGroup>\n</Project>\n",
        tfm
    );
    fs::write(&project, csproj)?;
    let program = dir.path().join("Program.cs");
    match payload {
        Payload::Inline(code) | Payload::Stdin(code) => fs::write(&program, ensure_newline(code))?,
        Payload::File(path) => {
            fs::copy(path, &program)?;
        }
    }
    let out = capture(
        Command::new(&dotnet)
            .arg("run")
            .arg("--project")
            .arg(&project)
            .arg("--nologo")
            .current_dir(dir.path()),
    )?;
    Ok(emit(&out))
}
