//! Language engines: how each language executes inline code, files and
//! code read from stdin.

use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

use crate::bail;
use crate::error::{Context, Error, Result};
use crate::sys::{self, capture, display, emit, feed_and_wait, find_tool, spawn_piped, TempDir, TempFile};

#[derive(Debug, Clone)]
pub enum Payload {
    Inline(String),
    File(PathBuf),
    Stdin(String),
