// ---------------------------------------------------------------- python ---

fn python(payload: &Payload) -> Result<i32> {
    let exe = tool_or(&["python3", "python", "py"], "--version", "python3");
    interpreter_with_flag(&exe, "-c", Some("-"), payload)
}

/// Interpreters that accept code through a flag (`-c`, `-e`) and read a
/// program from stdin.
fn interpreter_with_flag(exe: &Path, flag: &str, stdin_arg: Option<&str>, payload: &Payload) -> Result<i32> {
    match payload {
        Payload::Inline(code) => {
            let out = capture(Command::new(exe).arg(flag).arg(code))?;
            Ok(emit(&out))
        }
        Payload::File(path) => {
            let out = capture(Command::new(exe).arg(path))?;
            Ok(emit(&out))
        }
        Payload::Stdin(code) => {
            let mut cmd = Command::new(exe);
            if let Some(a) = stdin_arg {
                cmd.arg(a);
            }
            let child = spawn_piped(&mut cmd)
                .with_context(|| format!("failed to start {} for stdin execution", display(exe)))?;
            let out = feed_and_wait(child, code)?;
            Ok(emit(&out))
        }
    }
}

fn bash(payload: &Payload) -> Result<i32> {
    let exe = tool_or(&["bash", "sh"], "--version", "/bin/bash");
    interpreter_with_flag(&exe, "-c", None, payload)
}

fn javascript(payload: &Payload) -> Result<i32> {
