// ------------------------------------------------------------------- zig ---

fn indent_body(code: &str, pad: &str) -> String {
    if code.trim().is_empty() {
        return String::new();
    }
    let mut body = String::new();
    for line in code.lines() {
        if line.trim().is_empty() {
            body.push('\n');
        } else {
            body.push_str(pad);
            body.push_str(line);
            body.push('\n');
        }
    }
    body
}

