}

fn run_binary(binary: &Path) -> Result<i32> {
    let out = capture(&mut Command::new(binary))
        .with_context(|| format!("failed to execute compiled binary {}", display(binary)))?;
    Ok(emit(&out))
}

// --------------------------------------------------------------- c / c++ ---

struct CFamily {
    prefix: &'static str,
    source: &'static str,
    binary: &'static str,
    label: &'static str,
    candidates: &'static [&'static str],
    std: &'static str,
    missing: &'static str,
    wrap: bool,
}

const C_FAMILY_C: CFamily = CFamily {
    prefix: "run-c",
    source: "main.c",
    binary: "run_c_binary",
    label: "C",
    candidates: &["cc", "clang", "gcc"],
    std: "-std=c11",
    missing: "C support requires a C compiler such as `cc`, `clang`, or `gcc`. Install one and ensure it is on your PATH.",
    wrap: true,
};

const C_FAMILY_CPP: CFamily = CFamily {
    prefix: "run-cpp",
    source: "main.cpp",
    binary: "run_cpp_binary",
    label: "C++",
    candidates: &["c++", "clang++", "g++"],
    std: "-std=c++17",
    missing: "C++ support requires a C++ compiler such as `c++`, `clang++`, or `g++`. Install one and ensure it is on your PATH.",
    wrap: false,
};

pub fn wrap_c(code: &str) -> String {
    if code.contains("#include") || code.contains("main(") {
        return code.to_string();
    }
    format!(
        "#include <stdio.h>\n\nint main(void)\n{{\n{}    return 0;\n}}\n",
        indent_body(code, "    ")
    )
}

fn c_family(payload: &Payload, spec: &CFamily) -> Result<i32> {
    let dir = TempDir::new(spec.prefix)?;
    let source = dir.path().join(spec.source);
    match payload {
        Payload::Inline(code) | Payload::Stdin(code) => {
            let text = if spec.wrap { wrap_c(code) } else { code.clone() };
            fs::write(&source, text)?;
        }
        Payload::File(path) => {
            fs::copy(path, &source).with_context(|| {
                format!(
                    "failed to copy {} source from {} to {}",
                    spec.label,
                    display(path),
                    display(&source)
                )
            })?;
        }
    }
    let compiler = require(spec.candidates, "--version", spec.missing)?;
    let binary = dir.path().join(spec.binary);
    let out = Command::new(&compiler)
        .arg(&source)
        .arg(spec.std)
        .args(["-O0", "-Wall", "-Wextra", "-o"])
        .arg(&binary)
        .stdin(std::process::Stdio::null())
        .output()
        .with_context(|| format!("failed to invoke {}", display(&compiler)))?;
    if !out.status.success() {
        return Ok(emit(&out));
    }
    run_binary(&binary)
}

// ------------------------------------------------------------------ java ---

fn split_imports(code: &str, prefixes: &[&str]) -> (Vec<String>, Vec<String>) {
    let mut imports = Vec::new();
    let mut body = Vec::new();
    for line in code.lines() {
        let t = line.trim_start();
        if prefixes.iter().any(|p| t.starts_with(p)) {
            imports.push(line.trim().to_string());
        } else {
            body.push(line.to_string());
        }
    }
    (imports, body)
}

fn java(payload: &Payload) -> Result<i32> {
    let javac = require(
        &["javac"],
        "-version",
        "Java support requires the `javac` compiler. Install the JDK from https://adoptium.net/ or your vendor of choice and ensure it is on your PATH.",
    )?;
    let java = find_tool(&["java"], "-version");
    let dir = TempDir::new("run-java")?;
    let (source, class) = match payload {
        Payload::Inline(code) | Payload::Stdin(code) => {
            let text = if code.contains("class ") {
                code.clone()
            } else {
                let (imports, body) = split_imports(code, &["import "]);
                let mut s = String::new();
                if !imports.is_empty() {
                    s.push_str(&imports.join("\n"));
                    s.push_str("\n\n");
                }
                s.push_str("public class Main {\n    public static void main(String[] args) throws Exception {\n");
                s.push_str(&indent_body(&body.join("\n"), "        "));
                s.push_str("    }\n}\n");
                s
            };
            let f = dir.path().join("Main.java");
            fs::write(&f, text)?;
            (f, "Main".to_string())
        }
        Payload::File(path) => {
            let name = file_name(path);
            let f = dir.path().join(&name);
            fs::copy(path, &f)?;
            let stem = path
                .file_stem()
                .map(|s| s.to_string_lossy().into_owned())
                .unwrap_or_else(|| "Main".to_string());
            (f, stem)
        }
    };
    let out = Command::new(&javac)
        .arg("-d")
        .arg(dir.path())
        .arg(&source)
        .stdin(std::process::Stdio::null())
        .output()
        .with_context(|| format!("failed to invoke {}", display(&javac)))?;
    if !out.status.success() {
        return Ok(emit(&out));
    }
    let java = match java {
        Some(j) => j,
        None => bail!("Java support requires the `java` runtime. Install the JDK from https://adoptium.net/ or your vendor of choice and ensure it is on your PATH."),
    };
    let out = capture(Command::new(&java).arg("-cp").arg(dir.path()).arg(&class))?;
    Ok(emit(&out))
}

// ---------------------------------------------------------------- kotlin ---

fn kotlin(payload: &Payload) -> Result<i32> {
    let kotlinc = require(
        &["kotlinc"],
