            } else {
                let (imports, body) = split_imports(code, &["import "]);
                let mut s = String::new();
                if !imports.is_empty() {
                    s.push_str(&imports.join("\n"));
                    s.push_str("\n\n");
                }
                s.push_str("fun main() {\n");
                s.push_str(&indent_body(&body.join("\n"), "    "));
                s.push_str("}\n");
                s
            };
