//! Minimal raw-mode line editor (emacs style key bindings) used by the REPL.

use std::io::{self, Read, Write};
use std::os::raw::c_int;

#[repr(C)]
#[derive(Clone, Copy)]
struct Termios {
    c_iflag: u32,
    c_oflag: u32,
    c_cflag: u32,
    c_lflag: u32,
    c_line: u8,
    c_cc: [u8; 32],
    c_ispeed: u32,
    c_ospeed: u32,
}

extern "C" {
    fn tcgetattr(fd: c_int, termios: *mut Termios) -> c_int;
    fn tcsetattr(fd: c_int, optional_actions: c_int, termios: *const Termios) -> c_int;
    fn isatty(fd: c_int) -> c_int;
}

const BRKINT: u32 = 0o2;
const INPCK: u32 = 0o20;
const ISTRIP: u32 = 0o40;
const ICRNL: u32 = 0o400;
const IXON: u32 = 0o2000;
const OPOST: u32 = 0o1;
const CS8: u32 = 0o60;
const ISIG: u32 = 0o1;
const ICANON: u32 = 0o2;
const ECHO: u32 = 0o10;
const IEXTEN: u32 = 0o100000;
const VTIME: usize = 5;
const VMIN: usize = 6;
const TCSADRAIN: c_int = 1;

struct RawGuard {
    orig: Termios,
}

impl RawGuard {
    fn enable() -> Option<RawGuard> {
        unsafe {
            if isatty(0) == 0 {
                return None;
            }
            let mut t: Termios = std::mem::zeroed();
            if tcgetattr(0, &mut t) != 0 {
                return None;
            }
            let orig = t;
            t.c_iflag &= !(BRKINT | ICRNL | INPCK | ISTRIP | IXON);
            t.c_oflag &= !OPOST;
            t.c_cflag |= CS8;
            t.c_lflag &= !(ECHO | ICANON | IEXTEN | ISIG);
            t.c_cc[VMIN] = 1;
            t.c_cc[VTIME] = 0;
            if tcsetattr(0, TCSADRAIN, &t) != 0 {
                return None;
            }
            Some(RawGuard { orig })
        }
    }
}

impl Drop for RawGuard {
    fn drop(&mut self) {
        unsafe {
            tcsetattr(0, TCSADRAIN, &self.orig);
        }
    }
}

pub enum ReadResult {
    Line(String),
    Interrupted,
    Eof,
}

pub struct Editor {
    pub history: Vec<String>,
    pub added: Vec<String>,
}

fn read_byte(stdin: &mut io::Stdin) -> Option<u8> {
    let mut b = [0u8; 1];
    match stdin.read(&mut b) {
        Ok(1) => Some(b[0]),
        _ => None,
    }
}

impl Editor {
    pub fn new() -> Editor {
        Editor { history: Vec::new(), added: Vec::new() }
    }

    pub fn add_history(&mut self, line: &str) {
        if line.is_empty() {
            return;
        }
        if self.history.last().map(|s| s == line).unwrap_or(false) {
            return;
        }
        self.history.push(line.to_string());
        self.added.push(line.to_string());
