//! Persistent REPL sessions. Each session accumulates successfully executed
//! snippets, re-runs the whole program for every new snippet and only shows
//! the output that is new compared to the previous successful run.

use std::fs;
use std::path::PathBuf;
use std::process::{Command, Stdio};
use std::time::Instant;

use crate::engines::{self, Outcome, Payload};
use crate::error::{Context, Error, Result};
use crate::sys::{self, display, find_tool, TempDir};

pub struct Session {
    pub lang: &'static str,
    committed: Vec<String>,
    prev_stdout: String,
    prev_stderr: String,
    dir: Option<TempDir>,
}

pub struct EvalReport {
    pub stdout: String,
    pub stderr: String,
    pub failure: Option<(i32, u128)>,
}

fn diff(prev: &str, new: &str) -> String {
    if new.starts_with(prev) {
        new[prev.len()..].to_string()
    } else {
        new.to_string()
    }
}

fn quote_aware_contains(code: &str, targets: &[char]) -> bool {
    let mut quote: Option<char> = None;
    let mut escaped = false;
    for c in code.chars() {
        if let Some(q) = quote {
            if escaped {
                escaped = false;
            } else if c == '\\' {
                escaped = true;
            } else if c == q {
                quote = None;
            }
            continue;
        }
        if c == '"' || c == '\'' {
            quote = Some(c);
            continue;
        }
        if targets.contains(&c) {
            return true;
        }
    }
    false
}

fn has_assignment(code: &str) -> bool {
    let chars: Vec<char> = code.chars().collect();
    let mut quote: Option<char> = None;
    for i in 0..chars.len() {
        let c = chars[i];
        if let Some(q) = quote {
            if c == q {
                quote = None;
            }
            continue;
        }
        if c == '"' || c == '\'' {
            quote = Some(c);
            continue;
        }
        if c == '=' {
            let prev = if i > 0 { chars[i - 1] } else { ' ' };
            let next = chars.get(i + 1).copied().unwrap_or(' ');
            if next == '=' || prev == '=' || prev == '!' || prev == '<' || prev == '>' {
                continue;
            }
            return true;
        }
    }
    false
}

const PY_STATEMENT_KEYWORDS: &[&str] = &[
    "assert", "async", "await", "break", "class", "continue", "def", "del", "elif", "else", "except",
    "finally", "for", "from", "global", "if", "import", "nonlocal", "pass", "raise", "return", "try",
    "while", "with", "yield",
];

fn first_word(code: &str) -> &str {
    let end = code
        .char_indices()
        .find(|(_, c)| !(c.is_alphanumeric() || *c == '_'))
        .map(|(i, _)| i)
        .unwrap_or(code.len());
    &code[..end]
}

fn python_is_expression(code: &str) -> bool {
    let t = code.trim();
    if t.is_empty() || t.contains('\n') {
        return false;
    }
    if PY_STATEMENT_KEYWORDS.contains(&first_word(t)) {
        return false;
    }
    if t.starts_with("print(") || t.starts_with("print (") {
        return false;
    }
    if quote_aware_contains(t, &['#', ';']) || has_assignment(t) {
        return false;
    }
    true
}

fn indent(code: &str, pad: &str) -> String {
    let mut s = String::new();
    for line in code.lines() {
        if line.trim().is_empty() {
            s.push('\n');
        } else {
            s.push_str(pad);
            s.push_str(line);
            s.push('\n');
        }
    }
    s
}

struct Program {
    text: String,
}

impl Session {
    pub fn new(lang: &'static str) -> Session {
        Session { lang, committed: Vec::new(), prev_stdout: String::new(), prev_stderr: String::new(), dir: None }
    }

    pub fn reset(&mut self) {
        self.committed.clear();
        self.prev_stdout.clear();
        self.prev_stderr.clear();
        self.dir = None;
    }

    fn session_dir(&mut self) -> Result<PathBuf> {
        if self.dir.is_none() {
            self.dir = Some(TempDir::new(&format!("run-{}-repl", self.lang))?);
        }
        Ok(self.dir.as_ref().unwrap().path().to_path_buf())
    }

    /// Evaluate a snippet, returning what should be displayed.
    pub fn eval(&mut self, code: &str) -> Result<EvalReport> {
        let start = Instant::now();
        let candidates = self.candidates(code);
        let mut last: Option<(String, Outcome)> = None;
        for cand in candidates {
            let outcome = self.run_with(&cand)?;
            let ok = outcome.success();
            last = Some((cand, outcome));
            if ok {
                break;
            }
        }
        let (cand, outcome) = last.expect("at least one candidate");
        let elapsed = start.elapsed().as_millis();
        let stdout = String::from_utf8_lossy(&outcome.stdout).into_owned();
        let stderr = String::from_utf8_lossy(&outcome.stderr).into_owned();
        let report = EvalReport {
            stdout: diff(&self.prev_stdout, &stdout),
            stderr: diff(&self.prev_stderr, &stderr),
            failure: if outcome.success() { None } else { Some((outcome.code, elapsed)) },
        };
        if outcome.success() {
            self.committed.push(cand);
            self.prev_stdout = stdout;
            self.prev_stderr = stderr;
        }
        Ok(report)
    }

    /// Alternative renderings of the snippet, tried in order.
    fn candidates(&self, code: &str) -> Vec<String> {
        let n = self.committed.len();
        let t = code.trim();
        match self.lang {
            "python" => {
                if python_is_expression(code) {
                    vec![
                        format!("__run_value_{n} = ({t})\nprint(repr(__run_value_{n}), flush=True)\n"),
                        format!("{}\n", code.trim_end()),
                    ]
                } else {
                    vec![format!("{}\n", code.trim_end())]
                }
            }
            "perl" => {
                if !t.ends_with(';') && !t.ends_with('}') && !t.contains('\n') {
                    vec![format!("say({});\n", t), format!("{}\n", t)]
                } else {
                    vec![format!("{}\n", code.trim_end())]
                }
            }
            "rust" | "cpp" | "c" | "go" => {
                if !t.ends_with(';') && !t.ends_with('}') && !t.contains('\n') && !is_item(self.lang, t) {
                    vec![format!("@expr {}", t), t.to_string()]
                } else {
                    vec![t.to_string()]
                }
            }
            _ => vec![format!("{}\n", code.trim_end())],
        }
    }

    fn run_with(&mut self, cand: &str) -> Result<Outcome> {
        let mut snippets = self.committed.clone();
        snippets.push(cand.to_string());
        match self.lang {
            "python" => {
