                fs::write(&file, text)?;
                let exe = find_tool(&["python3", "python", "py"], "--version").unwrap_or_else(|| PathBuf::from("python3"));
                run_captured(Command::new(&exe).arg(&file).current_dir(&dir)).with_context(|| {
                    format!("failed to run python session script {} with {}", display(&file), display(&exe))
                })
            }
            "bash" => {
                let dir = self.session_dir()?;
                let file = dir.join("session.sh");
                let mut text = String::from("#!/usr/bin/env bash\nset -e\n");
                for s in &snippets {
                    text.push_str(s);
                }
                fs::write(&file, text)?;
                let exe = find_tool(&["bash", "sh"], "--version").unwrap_or_else(|| PathBuf::from("/bin/bash"));
                run_captured(Command::new(&exe).arg(&file).current_dir(&dir)).with_context(|| {
                    format!("failed to run bash session script {} with {}", display(&file), display(&exe))
                })
            }
            "perl" => {
                let exe = find_tool(&["perl"], "-v").ok_or_else(|| {
                    Error::msg("Perl support requires the `perl` executable. Install Perl from https://www.perl.org/get.html and ensure `perl` is on your PATH.")
                })?;
                let dir = self.session_dir()?;
                let file = dir.join("session.pl");
                let mut text = String::from("use feature 'say';\nuse strict;\nuse warnings;\n\n");
                for s in &snippets {
                    text.push_str(s);
                }
                fs::write(&file, text)?;
                run_captured(Command::new(&exe).arg(&file).current_dir(&dir)).with_context(|| {
                    format!("failed to run perl session script {} with {}", display(&file), display(&exe))
                })
            }
            "rust" => self.run_rust(&snippets),
            "go" => self.run_go(&snippets),
            "c" | "cpp" => self.run_c_family(&snippets),
            _ => {
                let code: String = snippets.concat();
                engines::execute(self.lang, &Payload::Inline(code))
            }
        }
    }

    fn run_rust(&mut self, snippets: &[String]) -> Result<Outcome> {
        let rustc = find_tool(&["rustc"], "--version").ok_or_else(|| {
            Error::msg("Rust support requires the `rustc` executable. Install it via Rustup and ensure it is on your PATH.")
        })?;
        let (items, body) = split_items("rust", snippets, |e| format!("__print({});", e));
        let mut text = String::from(
            "#![allow(unused_variables, unused_assignments, unused_mut, dead_code, unused_imports)]\nuse std::fmt::Debug;\nfn __print<T: Debug>(value: T) {\n    println!(\"{:?}\", value);\n}\n",
        );
        for i in &items {
            text.push_str(i);
            text.push('\n');
        }
        text.push_str("fn main() {\n");
        text.push_str(&indent(&body.join("\n"), "    "));
        text.push_str("}\n");
        let dir = TempDir::new(".tmp")?;
        let file = dir.path().join("session.rs");
        fs::write(&file, text)?;
        let binary = dir.path().join("session_bin");
        let out = Command::new(&rustc)
            .args(["--color=never", "--edition=2021"])
            .arg(&file)
            .arg("-o")
            .arg(&binary)
            .stdin(Stdio::null())
            .output()?;
        if !out.status.success() {
            return Ok(Outcome::from_output(&out));
        }
        run_captured(&mut Command::new(&binary))
    }

    fn run_go(&mut self, snippets: &[String]) -> Result<Outcome> {
        let go = find_tool(&["go"], "version").ok_or_else(|| {
            Error::msg("Go support requires the `go` executable. Install it from https://go.dev/dl/ and ensure it is on your PATH.")
        })?;
        let mut imports = vec!["\"fmt\"".to_string()];
        let mut decls = Vec::new();
        let mut body = Vec::new();
        for s in snippets {
            let t = s.trim();
            if let Some(rest) = t.strip_prefix("@expr ") {
                body.push(format!("__print({})", rest));
            } else if let Some(rest) = t.strip_prefix("import ") {
                let imp = rest.trim().to_string();
                if !imports.contains(&imp) {
                    imports.push(imp);
                }
            } else if t.starts_with("func ") || t.starts_with("type ") {
                decls.push(t.to_string());
            } else {
                body.push(t.to_string());
                if let Some(idx) = t.find(":=") {
                    let lhs = &t[..idx];
                    if !t.starts_with("for ") && !t.starts_with("if ") {
                        for name in lhs.split(',') {
                            let name = name.trim();
                            if !name.is_empty() && name != "_" {
                                body.push(format!("_ = {}", name));
                            }
                        }
                    }
                }
            }
        }
        let mut text = String::from("package main\n\nimport (\n");
        for i in &imports {
            text.push_str(&format!("\t{}\n", i));
        }
        text.push_str(")\n\nfunc __print(value interface{}) {\n\tif s, ok := value.(string); ok {\n\t\tfmt.Println(s)\n\t\treturn\n\t}\n\tfmt.Printf(\"%#v\\n\", value)\n}\n\n");
        for d in &decls {
            text.push_str(d);
            text.push_str("\n\n");
        }
        text.push_str("func main() {\n");
        text.push_str(&indent(&body.join("\n"), "\t"));
        text.push_str("}\n");
        let dir = TempDir::new(".tmp")?;
        fs::write(dir.path().join("main.go"), text)?;
        run_captured(
            Command::new(&go)
                .arg("run")
                .arg("main.go")
                .current_dir(dir.path())
                .env("GO111MODULE", "off"),
        )
    }

    fn run_c_family(&mut self, snippets: &[String]) -> Result<Outcome> {
        let cpp = self.lang == "cpp";
        let compiler = if cpp {
            find_tool(&["c++", "clang++", "g++"], "--version").ok_or_else(|| {
                Error::msg("C++ support requires a C++ compiler such as `c++`, `clang++`, or `g++`. Install one and ensure it is on your PATH.")
            })?
        } else {
            find_tool(&["cc", "clang", "gcc"], "--version").ok_or_else(|| {
                Error::msg("C support requires a C compiler such as `cc`, `clang`, or `gcc`. Install one and ensure it is on your PATH.")
            })?
        };
        let printer = |e: &str| {
            if cpp {
                format!("std::cout << ({}) << std::endl;", e)
            } else {
                format!("__run_print({});", e)
            }
        };
        let (items, body) = split_items(self.lang, snippets, printer);
        let mut text = String::new();
        if cpp {
            for h in [
                "iostream", "iomanip", "string", "vector", "map", "set", "unordered_map", "unordered_set", "deque",
                "list", "queue", "stack", "memory", "functional", "algorithm", "numeric", "cmath",
            ] {
                text.push_str(&format!("#include <{}>\n", h));
            }
            text.push_str("\nusing namespace std;\n\n");
        } else {
            for h in ["stdio.h", "stdlib.h", "string.h", "stdbool.h", "math.h"] {
                text.push_str(&format!("#include <{}>\n", h));
            }
            text.push_str(concat!(
                "\n#define __run_print(x) _Generic((x), \\\n",
                "    char: printf(\"%c\\n\", (x)), \\\n",
                "    int: printf(\"%d\\n\", (x)), \\\n",
                "    long: printf(\"%ld\\n\", (x)), \\\n",
                "    long long: printf(\"%lld\\n\", (x)), \\\n",
                "    unsigned int: printf(\"%u\\n\", (x)), \\\n",
                "    unsigned long: printf(\"%lu\\n\", (x)), \\\n",
                "    float: printf(\"%g\\n\", (double)(x)), \\\n",
                "    double: printf(\"%g\\n\", (x)), \\\n",
                "    char *: printf(\"%s\\n\", (x)), \\\n",
                "    const char *: printf(\"%s\\n\", (x)), \\\n",
                "    default: printf(\"%p\\n\", (void *)(size_t)(x)))\n\n"
            ));
        }
        for i in &items {
            text.push_str(i);
            text.push_str("\n\n");
        }
        if cpp {
            text.push_str("int main()\n{\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    cout.setf(std::ios::boolalpha);\n");
        } else {
            text.push_str("int main(void)\n{\n");
        }
        text.push_str(&indent(&body.join("\n"), "    "));
        text.push_str("    return 0;\n}\n");
        let dir = self.session_dir()?;
        let (src, bin, std) = if cpp {
            (dir.join("main.cpp"), dir.join("run_cpp_binary"), "-std=c++17")
        } else {
            (dir.join("main.c"), dir.join("run_c_binary"), "-std=c11")
        };
        fs::write(&src, text)?;
        let out = Command::new(&compiler)
            .arg(&src)
            .arg(std)
            .args(["-O0", "-w", "-o"])
            .arg(&bin)
            .stdin(Stdio::null())
            .output()?;
        if !out.status.success() {
            return Ok(Outcome::from_output(&out));
        }
        run_captured(&mut Command::new(&bin))
    }
}

fn is_item(lang: &str, t: &str) -> bool {
    let prefixes: &[&str] = match lang {
        "rust" => &["fn ", "pub ", "use ", "struct ", "enum ", "impl ", "trait ", "mod ", "#[", "const ", "static ", "type ", "extern "],
        "go" => &["func ", "import ", "type ", "var ", "const ", "for ", "if ", "switch ", "go ", "defer ", "return"],
        _ => &["#", "struct ", "typedef ", "enum ", "union ", "template", "class ", "namespace ", "using "],
    };
    prefixes.iter().any(|p| t.starts_with(p)) || t.contains(":=") || has_assignment(t)
}

/// Split snippets into top-level items and statements for `main`.
fn split_items(lang: &str, snippets: &[String], printer: impl Fn(&str) -> String) -> (Vec<String>, Vec<String>) {
    let mut items = Vec::new();
    let mut body = Vec::new();
    for s in snippets {
        let t = s.trim();
        if let Some(rest) = t.strip_prefix("@expr ") {
            body.push(printer(rest));
            continue;
        }
        let is_top = match lang {
            "rust" => ["fn ", "pub ", "use ", "struct ", "enum ", "impl ", "trait ", "mod ", "#[", "extern "].iter().any(|p| t.starts_with(p)),
            _ => {
                t.starts_with('#')
                    || t.starts_with("struct ") && t.ends_with("};")
                    || t.starts_with("typedef ")
                    || t.starts_with("template")
                    || t.starts_with("class ")
                    || t.starts_with("namespace ")
                    || t.starts_with("using ")
                    || looks_like_function_definition(t)
            }
        };
        if is_top {
            items.push(t.to_string());
        } else {
            body.push(t.to_string());
        }
    }
    (items, body)
}

fn looks_like_function_definition(t: &str) -> bool {
    // e.g. `int f(void) { return 2; }`
    if let (Some(p), Some(b)) = (t.find('('), t.find('{')) {
        if p < b && t.ends_with('}') {
            let head = &t[..p];
            let words: Vec<&str> = head.split_whitespace().collect();
            return words.len() >= 2 && !head.contains('=');
        }
    }
    false
}

fn run_captured(cmd: &mut Command) -> Result<Outcome> {
    let out = cmd.stdin(Stdio::inherit()).stdout(Stdio::piped()).stderr(Stdio::piped()).output()?;
    Ok(Outcome::from_output(&out))
}

