                "    float: printf(\"%g\\n\", (double)(x)), \\\n",
                "    double: printf(\"%g\\n\", (x)), \\\n",
                "    char *: printf(\"%s\\n\", (x)), \\\n",
                "    const char *: printf(\"%s\\n\", (x)), \\\n",
                "    default: printf(\"%p\\n\", (void *)(size_t)(x)))\n\n"
            ));
        }
        for i in &items {
            text.push_str(i);
            text.push_str("\n\n");
        }
        if cpp {
            text.push_str("int main()\n{\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    cout.setf(std::ios::boolalpha);\n");
        } else {
            text.push_str("int main(void)\n{\n");
        }
        text.push_str(&indent(&body.join("\n"), "    "));
        text.push_str("    return 0;\n}\n");
        let dir = self.session_dir()?;
        let (src, bin, std) = if cpp {
            (dir.join("main.cpp"), dir.join("run_cpp_binary"), "-std=c++17")
        } else {
            (dir.join("main.c"), dir.join("run_c_binary"), "-std=c11")
        };
        fs::write(&src, text)?;
        let out = Command::new(&compiler)
            .arg(&src)
