pub fn run(initial: Option<&'static str>, detect_enabled: bool) -> Result<i32> {
    let mut repl = Repl {
        current: initial.unwrap_or("python"),
        detect: initial.is_none() && detect_enabled,
        sessions: HashMap::new(),
        needs_newline: false,
    };
    let mut editor = Editor::new();
    load_history(&mut editor);
    repl.println("run universal REPL. Type :help for commands.");
    loop {
        repl.ensure_fresh_line();
        let prompt = format!("{}>>> ", repl.current);
        let line = match editor.readline(&prompt) {
            ReadResult::Line(l) => l,
            ReadResult::Interrupted => continue,
            ReadResult::Eof => {
                repl.println("bye");
                break;
            }
        };
        editor.add_history(&line);
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        if trimmed.starts_with(':') {
            if repl.command(trimmed)? {
                break;
            }
            continue;
        }
        let mut buffer = line.clone();
        let python_block = repl.current == "python" && line.trim_end().ends_with(':');
        loop {
            let more = if python_block { true } else { repl.needs_more(&buffer) };
            if !more {
                break;
            }
            match editor.readline("... ") {
                ReadResult::Line(l) => {
                    editor.add_history(&l);
                    if python_block && l.trim().is_empty() {
                        break;
                    }
                    buffer.push('\n');
                    buffer.push_str(&l);
                    if !python_block && bracket_balance(&buffer) <= 0 {
                        break;
                    }
                }
                ReadResult::Interrupted => {
                    buffer.clear();
                    break;
                }
                ReadResult::Eof => break,
            }
        }
        if buffer.trim().is_empty() {
            continue;
        }
        repl.execute(&buffer)?;
    }
    save_history(&editor);
    Ok(0)
}
