    }

    fn needs_more(&self, buffer: &str) -> bool {
        if bracket_balance(buffer) > 0 {
            return true;
        }
        if self.current == "python" {
            let first = buffer.lines().next().unwrap_or("");
            if first.trim_end().ends_with(':') {
                // Block statements end with an empty line.
                return !buffer.ends_with("\n\n") && buffer.lines().count() >= 1 && !buffer.ends_with('\u{0}');
            }
        }
        false
    }

    fn execute(&mut self, code: &str) -> Result<()> {
        if self.detect {
            if let Some(l) = detect::detect(code) {
                if l != self.current {
                    let from = self.current;
                    self.println(&format!("[auto-detect] switching {} \u{2192} {}", from, l));
                    self.current = l;
                }
            }
        }
        let lang = self.current;
        let session = self.sessions.entry(lang).or_insert_with(|| Session::new(lang));
        let report = session.eval(code)?;
        self.print(&report.stdout);
        self.eprint(&report.stderr);
        if let Some((code, ms)) = report.failure {
            self.ensure_fresh_line();
            self.println(&format!("[exit code {}] ({}ms)", code, ms));
        }
        Ok(())
    }
}

pub fn run(initial: Option<&'static str>, detect_enabled: bool) -> Result<i32> {
    let mut repl = Repl {
        current: initial.unwrap_or("python"),
        detect: initial.is_none() && detect_enabled,
        sessions: HashMap::new(),
        needs_newline: false,
    };
    let mut editor = Editor::new();
    load_history(&mut editor);
    repl.println("run universal REPL. Type :help for commands.");
    loop {
        repl.ensure_fresh_line();
        let prompt = format!("{}>>> ", repl.current);
        let line = match editor.readline(&prompt) {
            ReadResult::Line(l) => l,
            ReadResult::Interrupted => continue,
            ReadResult::Eof => {
                repl.println("bye");
                break;
            }
        };
        editor.add_history(&line);
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        if trimmed.starts_with(':') {
            if repl.command(trimmed)? {
                break;
            }
            continue;
        }
        let mut buffer = line.clone();
        let python_block = repl.current == "python" && line.trim_end().ends_with(':');
        loop {
            let more = if python_block { true } else { repl.needs_more(&buffer) };
            if !more {
                break;
            }
            match editor.readline("... ") {
                ReadResult::Line(l) => {
                    editor.add_history(&l);
                    if python_block && l.trim().is_empty() {
                        break;
                    }
                    buffer.push('\n');
                    buffer.push_str(&l);
                    if !python_block && bracket_balance(&buffer) <= 0 {
                        break;
                    }
                }
                ReadResult::Interrupted => {
                    buffer.clear();
                    break;
                }
                ReadResult::Eof => break,
            }
        }
        if buffer.trim().is_empty() {
            continue;
        }
        repl.execute(&buffer)?;
    }
    save_history(&editor);
    Ok(0)
}
