        }
        text.push_str(&indent(&body.join("\n"), "    "));
        text.push_str("    return 0;\n}\n");
        let tmp;
        let dir = if cpp {
            self.session_dir()?
        } else {
            tmp = TempDir::new(".tmp")?;
            tmp.path().to_path_buf()
        };
        let (src, bin, std) = if cpp {
            (dir.join("main.cpp"), dir.join("run_cpp_binary"), "-std=c++17")
        } else {
            (dir.join("main.c"), dir.join("run_c_binary"), "-std=c11")
        };
        fs::write(&src, text)?;
        let out = Command::new(&compiler)
            .arg(&src)
            .arg(std)
            .args(["-O0", "-Wall", "-Wextra", "-o"])
            .arg(&bin)
            .stdin(Stdio::null())
            .output()?;
        if !out.status.success() {
            return Ok(Outcome::from_output(&out));
        }
        run_captured(&mut Command::new(&bin))
    }
}

