            s.push_str(&format!("println({});\\n", l));
            s
        }
        _ => code.to_string(),
    }
}

fn groovy_is_expression(line: &str) -> bool {
    const STATEMENTS: &[&str] = &[
        "println", "print ", "print(", "class ", "interface ", "enum ", "import ", "package ", "if", "for",
        "return", "try", "throw", "switch",
    ];
    if STATEMENTS.iter().any(|k| line.starts_with(k)) {
        return false;
    }
    if line.starts_with("def ") && line.contains('(') {
        return false;
    }
    true
}

